module optimal_assembly (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    \n    // Configuration: symbols (8 characters, each 8 bits)\n    input wire [7:0] symbol_in [0:7],\n    \n    // Configuration: time table (8x8, each 32 bits)\n    input wire [31:0] time_table_in [0:7][0:7],\n    \n    // Configuration: result table (8x8, each 8 bits, representing symbol index)\n    input wire [7:0] result_table_in [0:7][0:7],\n    \n    // String to assemble: 10 symbols, each 8 bits (indices)\n    input wire [7:0] string_in [0:9],\n    input wire [3:0] length_in,\n    \n    // Output\n    output reg [31:0] result_time,\n    output reg [7:0] result_symbol,\n    output reg done\n);\n\n// Parameters\nlocalparam NUM_SYMBOLS = 8;\nlocalparam MAX_LENGTH = 10;\nlocalparam [31:0] INF = 32'hFFFFFFFF;\n\n// State definitions\nlocalparam [2:0] S_IDLE       = 3'd0;\nlocalparam [2:0] S_INIT_ALL   = 3'd1;\nlocalparam [2:0] S_INIT_DIAG  = 3'd2;\nlocalparam [2:0] S_COMP_READ  = 3'd3;\nlocalparam [2:0] S_COMP_WRITE = 3'd4;\nlocalparam [2:0] S_FIND_BEST  = 3'd5;\nlocalparam [2:0] S_OUTPUT     = 3'd6;\n\nreg [2:0] state;\nreg [2:0] next_state;\n\n// Counters\nreg [3:0] init_i, init_j, init_t;       // Initialization counters\nreg [3:0] comp_length, comp_start;      // Computation counters\nreg [3:0] comp_split;\nreg [2:0] comp_left, comp_right;\nreg [3:0] best_t;                       // Best symbol finder\n\n// DP table\nreg [31:0] dp [0:9][0:9][0:7];          // [start][end][symbol]\n\n// Configuration latches\nreg [7:0] lat_symbol[0:7];\nreg [31:0] lat_time_table[0:7][0:7];\nreg [7:0] lat_result_table[0:7][0:7];\nreg [7:0] lat_string[0:9];\nreg [3:0] lat_length;\n\n// Temporary storage\nreg [31:0] dp_left_val;\nreg [31:0] dp_right_val;\n\ninteger i, j, k;  // Loop variables\n\n// Counter increment helper\ntask automatic inc_counts;\n    begin\n        if (comp_right < NUM_SYMBOLS-1) \n            comp_right <= comp_right + 3'd1;\n        else begin\n            comp_right <= 3'd0;\n            if (comp_left < NUM_SYMBOLS-1)\n                comp_left <= comp_left + 3'd1;\n            else begin\n                comp_left <= 3'd0;\n                if (comp_split < comp_start + comp_length - 2)\n                    comp_split <= comp_split + 4'd1;\n                else begin\n                    comp_split <= comp_start;\n                    if (comp_start < lat_length - comp_length)\n                        comp_start <= comp_start + 4'd1;\n                    else begin\n                        comp_start <= 4'd0;\n                        if (comp_length < lat_length)\n                            comp_length <= comp_length + 4'd1;\n                        else\n                            comp_length <= 4'd0;\n                    end\n                end\n            end\n        end\n    end\nendtask\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        S_IDLE:      next_state = start ? S_INIT_ALL : S_IDLE;\n        S_INIT_ALL:  if (init_i==MAX_LENGTH-1 && init_j==MAX_LENGTH-1 && init_t==NUM_SYMBOLS-1)\n                            next_state = S_INIT_DIAG;\n        S_INIT_DIAG: if (init_i==lat_length-1 && init_t==NUM_SYMBOLS-1)\n                            next_state = (lat_length==1) ? S_FIND_BEST : S_COMP_READ;\n        S_COMP_READ: next_state = S_COMP_WRITE;\n        S_COMP_WRITE: if (comp_length >= lat_length || comp_length==4'd0)\n                            next_state = S_FIND_BEST;\n        S_FIND_BEST: if (best_t == NUM_SYMBOLS-1)\n                            next_state = S_OUTPUT;\n        S_OUTPUT:    next_state = S_IDLE;\n        default: next_state = S_IDLE;\n    endcase\nend\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        done <= 1'b0;\n        result_time <= 32'd0;\n        result_symbol <= 8'd0;\n        \n        // Initialize all DP entries to INF\n        for (i=0; i<MAX_LENGTH; i=i+1) begin\n            for (j=0; j<MAX_LENGTH; j=j+1) begin\n                for (k=0; k<NUM_SYMBOLS; k=k+1) begin\n                    dp[i][j][k] <= INF;\n                end\n            end\n        end\n        \n        // Reset counters\n        init_i <= 4'd0;\n        init_j <= 4'd0;\n        init_t <= 4'd0;\n        comp_length <= 4'd2;\n        comp_start <= 4'd0;\n        comp_split <= 4'd0;\n        comp_left <= 3'd0;\n        comp_right <= 3'd0;\n        best_t <= 4'd0;\n        \n    end else begin\n        state <= next_state;\n        \n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n            end\n            \n            S_INIT_ALL: begin\n                dp[init_i][init_j][init_t] <= INF;\n                if (init_t < NUM_SYMBOLS-1)\n                    init_t <= init_t + 4'd1;\n                else begin\n                    init_t <= 4'd0;\n                    if (init_j < MAX_LENGTH-1)\n                        init_j <= init_j + 4'd1;\n                    else begin\n                        init_j <= 4'd0;\n                        if (init_i < MAX_LENGTH-1)\n                            init_i <= init_i + 4'd1;\n                    end\n                end\n            end\n            \n            S_INIT_DIAG: begin\n                if (lat_string[init_i] == init_t[2:0])\n                    dp[init_i][init_i][init_t[2:0]] <= 32'd0;\n                \n                if (init_t < NUM_SYMBOLS-1)\n                    init_t <= init_t + 4'd1;\n                else begin\n                    init_t <= 4'd0;\n                    if (init_i < lat_length-1)\n                        init_i <= init_i + 4'd1;\n                end\n            end\n            \n            S_COMP_READ: begin\n                dp_left_val <= dp[comp_start][comp_split][comp_left];\n                dp_right_val <= dp[comp_split+1][comp_start+comp_length-1][comp_right];\n            end\n            \n            S_COMP_WRITE: begin\n                if (dp_left_val != INF && dp_right_val != INF) begin\n                    reg [31:0] total_time = dp_left_val + dp_right_val + lat_time_table[comp_left][comp_right];\n                    reg [7:0] res_symbol = lat_result_table[comp_left][comp_right];\n                    \n                    if (total_time < dp[comp_start][comp_start+comp_length-1][res_symbol])\n                        dp[comp_start][comp_start+comp_length-1][res_symbol] <= total_time;\n                end\n                \n                inc_counts();\n            end\n            \n            S_FIND_BEST: begin\n                if (best_t[2:0] == 3'd0) begin\n                    result_time <= dp[0][lat_length-1][0];\n                    result_symbol <= lat_symbol[0];\n                end\n                else if (dp[0][lat_length-1][best_t[2:0]] < result_time) begin\n                    result_time <= dp[0][lat_length-1][best_t[2:0]];\n                    result_symbol <= lat_symbol[best_t[2:0]];\n                end\n                \n                if (best_t < NUM_SYMBOLS-1)\n                    best_t <= best_t + 4'd1;\n            end\n            \n            S_OUTPUT: begin\n                done <= 1'b1;\n                best_t <= 4'd0;\n            end\n            \n            default: state <= S_IDLE;\n        endcase\n        \n        // Latch inputs at start\n        if (state == S_IDLE && start) begin\n            for (i=0; i<NUM_SYMBOLS; i=i+1) lat_symbol[i] <= symbol_in[i];\n            for (i=0; i<NUM_SYMBOLS; i=i+1) begin\n                for (j=0; j<NUM_SYMBOLS; j=j+1) begin\n                    lat_time_table[i][j] <= time_table_in[i][j];\n                    lat_result_table[i][j] <= result_table_in[i][j];\n                end\n            end\n            for (i=0; i<MAX_LENGTH; i=i+1)\n                lat_string[i] <= string_in[i];\n            lat_length <= length_in;\n        end\n    end\nend\n\nendmodule